function main() {
    var levels = parseInt(readLine(),10);
    var points = new Array();
    var count = 0;
    while(count < levels){
        var elem = parseInt(readLine(),10);
        points[count] = elem;
        count++;
    }
    var sum = 0;
    sum = points.reduce(function(a,b){
     return a + b     	
     },0)
    console.log(sum);
}
